import type { Column, DataValue } from '@tableau/extensions-api-types';
import type { Place } from '../types';
import places from './places.json';

/** [lat, lng, shapeId] as generated by scripts/build-places.mjs. */
type Entry = [number, number, string];
const COUNTRIES = places.countries as unknown as Record<string, Entry>;
const STATES = places.states as unknown as Record<string, Entry>;
const USA = COUNTRIES['united states'];

export interface Located {
  lat: number;
  lng: number;
  place: Place;
  /** The value that was recognized, as written in the data (e.g. "California", "FR"). */
  name: string;
}

/** Share of a column's non-null values that must match for it to count as a location column. */
const MIN_MATCH_RATE = 0.5;
const SAMPLE_ROWS = 500;

/** Must match normalize() in scripts/build-places.mjs. */
export function normalizePlace(s: string): string {
  return s
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[.'’]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/^the /, '');
}

export interface Geocoder {
  locate(row: DataValue[]): Located | null;
  /** e.g. "State/Province (US states), Country (countries)", for status messages. */
  describe: string;
}

/**
 * Picks the columns that hold country and/or US-state values and returns a function that
 * places each row at that area's centroid. Returns null if no column looks like locations.
 */
export function buildGeocoder(columns: Column[], rows: DataValue[][]): Geocoder | null {
  const sample = rows.slice(0, SAMPLE_ROWS);
  const candidates = columns.filter((c) => String(c.dataType) === 'string' || String(c.dataType) === 'int');

  /** Share of non-empty values in `column` (over `sampleRows`) found in `table`. */
  const matchRate = (column: Column, table: Record<string, Entry>, sampleRows: DataValue[][]) => {
    let values = 0;
    let hits = 0;
    for (const row of sampleRows) {
      const v = row[column.index]?.nativeValue;
      if (v === null || v === undefined || v === '') continue;
      values++;
      if (normalizePlace(String(v)) in table) hits++;
    }
    return values ? hits / values : 0;
  };

  // A column that is mostly US states isn't a country column even if some values
  // ("Georgia", "CA") are also country names or codes.
  const countryCol = candidates
    .map((c) => ({ c, country: matchRate(c, COUNTRIES, sample), state: matchRate(c, STATES, sample) }))
    .filter((s) => s.country >= MIN_MATCH_RATE && s.country > s.state)
    .sort((a, b) => b.country - a.country)[0]?.c;

  // With a country column, judge state columns only on US rows, so a worldwide
  // State/Province field still resolves its US states.
  const stateSample = countryCol ? sample.filter((row) => isUsa(lookup(COUNTRIES, row[countryCol.index]))) : sample;
  const stateCol = candidates
    .filter((c) => c !== countryCol)
    .map((c) => ({ c, state: matchRate(c, STATES, stateSample) }))
    .filter((s) => s.state >= MIN_MATCH_RATE)
    .sort((a, b) => b.state - a.state)[0]?.c;
  if (!stateCol && !countryCol) return null;

  return {
    locate(row) {
      const country = countryCol ? lookup(COUNTRIES, row[countryCol.index]) : null;
      // Only use the state when the row's country (if any) is the US.
      const nameOf = (c: Column) => String(row[c.index]?.formattedValue ?? row[c.index]?.nativeValue ?? '');
      if (stateCol && (!countryCol || isUsa(country))) {
        const state = lookup(STATES, row[stateCol.index]);
        if (state) return { lat: state[0], lng: state[1], place: { kind: 'state', id: state[2] }, name: nameOf(stateCol) };
      }
      return (
        country && {
          lat: country[0],
          lng: country[1],
          place: { kind: 'country', id: country[2] },
          name: nameOf(countryCol!),
        }
      );
    },
    describe: [
      stateCol && `${stateCol.fieldName} (US states)`,
      countryCol && `${countryCol.fieldName} (countries)`,
    ]
      .filter(Boolean)
      .join(', '),
  };
}

/** Looks up a single country or US-state name/code (used for sample data). */
export function locatePlace(name: string, kind: 'country' | 'state'): Located | null {
  const entry = (kind === 'state' ? STATES : COUNTRIES)[normalizePlace(name)];
  return entry ? { lat: entry[0], lng: entry[1], place: { kind, id: entry[2] }, name } : null;
}

function lookup(table: Record<string, Entry>, v: DataValue | undefined): Entry | null {
  const raw = v?.nativeValue;
  if (raw === null || raw === undefined || raw === '') return null;
  return table[normalizePlace(String(raw))] ?? null;
}

/** Aliases ("USA", "US", "840") map to equal but distinct arrays, so compare ids. */
function isUsa(entry: Entry | null): boolean {
  return !!entry && entry[2] === USA[2];
}
